from copy import deepcopy
from math import sqrt


def prepare_measurements(records, fields):
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a sequence")
    if not fields:
        raise ValueError("fields must be non-empty")
    if any(not isinstance(field, str) for field in fields):
        raise TypeError("field names must be strings")
    if any(not field for field in fields):
        raise ValueError("field names must be non-empty")
    if len(set(fields)) != len(fields):
        raise ValueError("field names must be unique")
    if not isinstance(records, (list, tuple)):
        raise TypeError("records must be a sequence")
    if any(not isinstance(record, dict) for record in records):
        raise TypeError("each record must be a dictionary")

    work = list(records)
    kept = []
    discarded = 0
    for record in work:
        reject = False
        for field in fields:
            value = record.get(field)
            if value is not None and value != "":
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    raise TypeError("measurement values must be numeric")
                if value == 0:
                    reject = True
        if reject:
            discarded += 1
        else:
            kept.append(record)

    stats = {}
    for field in fields:
        available = [
            float(record[field])
            for record in kept
            if record.get(field) not in (None, "")
        ]
        if not kept:
            mean = 0.0
        elif not available:
            raise ValueError("cannot impute a field with no available values")
        else:
            mean = sum(available) / len(available)

        for record in kept:
            if record.get(field) in (None, ""):
                record[field] = mean
            else:
                record[field] = float(record[field])

        if kept:
            variance = sum(
                (record[field] - mean) ** 2 for record in kept
            ) / len(kept)
        else:
            variance = 0.0
        scale = sqrt(variance) or 1.0

        for record in kept:
            record[field] = (record[field] - mean) / scale
        stats[field] = {"mean": mean, "scale": scale}

    return {"rows": kept, "discarded": discarded, "stats": stats}

